import{_ as d,a0 as n,w as o,s as p,I as i,x as e,a1 as t,A as l,ao as r}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const C=JSON.parse('{"title":"命令别名：保护和服务 | LCTT x X-CMD","titleTemplate":false,"description":"命令别名：保护和服务 | LCTT (201905) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"命令别名：保护和服务 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"命令别名：保护和服务 | LCTT (201905) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201905/20190107 Aliases- To Protect and Serve","title":"命令别名：保护和服务","tag":"201905","desc":""},"relativePath":"201905/20190107 Aliases- To Protect and Serve.md","filePath":"[post].md"}'),c={name:"201905/20190107 Aliases- To Protect and Serve.md"};function h(g,s,k,b,u,f){const a=n("Link");return o(),p("div",null,[s[18]||(s[18]=i("h1",{id:"命令别名-保护和服务",tabindex:"-1"},[e("命令别名：保护和服务 "),i("a",{class:"header-anchor",href:"#命令别名-保护和服务","aria-label":"Permalink to “命令别名：保护和服务”"},"​")],-1)),s[19]||(s[19]=i("blockquote",null,[i("p",null,"Linux shell 允许你将命令彼此链接在一起，一次触发执行复杂的操作，并且可以对此创建别名作为快捷方式。")],-1)),s[20]||(s[20]=i("p",null,[i("img",{src:"https://www.linux.com/sites/lcom/files/styles/rendered_file/public/prairie-path_1920.jpg?itok=wRARsM7p",alt:""})],-1)),i("p",null,[s[1]||(s[1]=e("让我们将继续我们的别名系列。到目前为止，你可能已经阅读了我们的",-1)),t(a,{href:"https://linux.cn/article-10377-1.html"},{default:l(()=>[...s[0]||(s[0]=[e("关于别名的第一篇文章",-1)])]),_:1}),s[2]||(s[2]=e("，并且应该非常清楚它们是如何为你省去很多麻烦的最简单方法。例如，你已经看到它们帮助我们减少了输入，让我们看看别名派上用场的其他几个案例。",-1))]),s[21]||(s[21]=r(`<h3 id="别名即快捷方式" tabindex="-1">别名即快捷方式 <a class="header-anchor" href="#别名即快捷方式" aria-label="Permalink to “别名即快捷方式”">​</a></h3><p>Linux shell 最美妙的事情之一是可以使用数以万计的选项和把命令连接在一起执行真正复杂的操作。好吧，也许这种美丽是在旁观者的眼中的，但是我们觉得这个功能很实用。</p><p>不利的一面是，你经常需要记得难以记忆或难以打字出来的命令组合。比如说硬盘上的空间非常宝贵，而你想要做一些清洁工作。你的第一步可能是寻找隐藏在你的家目录里的东西。你可以用来判断的一个标准是查找不再使用的内容。<code>ls</code> 可以帮助你：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -lct</span></span></code></pre></div><p>上面的命令显示了每个文件和目录的详细信息（<code>-l</code>），并显示了每一项上次访问的时间（<code>-c</code>），然后它按从最近访问到最少访问的顺序排序这个列表（<code>-t</code>）。</p><p>这难以记住吗？你可能不会每天都使用 <code>-c</code> 和 <code>-t</code> 选项，所以也许是吧。无论如何，定义一个别名，如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lt=&#39;ls -lct&#39;</span></span></code></pre></div><p>会更容易一些。</p><p>然后，你也可能希望列表首先显示最旧的文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>alias lo=&#39;lt -F | tac&#39;</span></span></code></pre></div><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/fig01_0.png?itok=crqTm_va" alt="aliases" title="aliases"></p><p><em>图 1：使用 lt 和 lo 别名。</em></p><p>这里有一些有趣的事情。首先，我们使用别名（<code>lt</code>）来创建另一个别名 —— 这是完全可以的。其次，我们将一个新参数传递给 <code>lt</code>（后者又通过 <code>lt</code> 别名的定义传递给了 <code>ls</code>）。</p><p><code>-F</code> 选项会将特殊符号附加到项目的名称后，以便更好地区分常规文件（没有符号）和可执行文件（附加了 <code>*</code>）、目录文件（以 <code>/</code> 结尾），以及所有链接文件、符号链接文件（以 <code>@</code> 符号结尾）等等。<code>-F</code> 选项是当你回归到单色终端的日子里，没有其他方法可以轻松看到列表项之间的差异时用的。在这里使用它是因为当你将输出从 <code>lt</code> 传递到 <code>tac</code> 时，你会丢失 <code>ls</code> 的颜色。</p><p>第三件我们需要注意的事情是我们使用了管道。管道用于你将一个命令的输出传递给另外一个命令时。第二个命令可以使用这些输出作为它的输入。在包括 Bash 在内的许多 shell 里，你可以使用管道符（<code>|</code>） 来做传递。</p><p>在这里，你将来自 <code>lt -F</code> 的输出导给 <code>tac</code>。<code>tac</code> 这个命令有点玩笑的意思，你或许听说过 <code>cat</code> 命令，它名义上用于将文件彼此连接（con<code>cat</code>），而在实践中，它被用于将一个文件的内容打印到终端。<code>tac</code> 做的事情一样，但是它是以逆序将接收到的内容输出出来。明白了吗？<code>cat</code> 和 <code>tac</code>，技术人有时候也挺有趣的。</p><p><code>cat</code> 和 <code>tac</code> 都能输出通过管道传递过来的内容，在这里，也就是一个按时间顺序排序的文件列表。</p><p>那么，在有些离题之后，最终我们得到的就是这个列表将当前目录中的文件和目录以新鲜度的逆序列出（即老的在前）。</p><p>最后你需要注意的是，当在当前目录或任何目录运行 <code>lt</code> 时：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 这可以工作：</span></span>
<span class="line"><span>lt</span></span>
<span class="line"><span># 这也可以：</span></span>
<span class="line"><span>lt /some/other/directory</span></span></code></pre></div><p>……而 <code>lo</code> 只能在当前目录奏效：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 这可工作：</span></span>
<span class="line"><span>lo</span></span>
<span class="line"><span># 而这不行：</span></span>
<span class="line"><span>lo /some/other/directory</span></span></code></pre></div><p>这是因为 Bash 会展开别名的组分。当你键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lt /some/other/directory</span></span></code></pre></div><p>Bash 实际上运行的是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -lct /some/other/directory</span></span></code></pre></div><p>这是一个有效的 Bash 命令。</p><p>而当你键入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lo /some/other/directory</span></span></code></pre></div><p>Bash 试图运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>ls -lct -F | tac /some/other/directory</span></span></code></pre></div><p>这不是一个有效的命令，主要是因为 <code>/some/other/directory</code> 是个目录，而 <code>cat</code> 和 <code>tac</code> 不能用于目录。</p><h3 id="更多的别名快捷方式" tabindex="-1">更多的别名快捷方式 <a class="header-anchor" href="#更多的别名快捷方式" aria-label="Permalink to “更多的别名快捷方式”">​</a></h3><ul><li><code>alias lll=&#39;ls -R&#39;</code> 会打印出目录的内容，并深入到子目录里面打印子目录的内容，以及子目录的子目录，等等。这是一个查看一个目录下所有内容的方式。</li><li><code>mkdir=&#39;mkdir -pv&#39;</code> 可以让你一次性创建目录下的目录。按照 <code>mkdir</code> 的基本形式，要创建一个包含子目录的目录，你必须这样：</li></ul><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir</span></span>
<span class="line"><span>mkdir newdir/subdir</span></span></code></pre></div><p>或这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir -p newdir/subdir</span></span></code></pre></div><p>而用这个别名你将只需要这样就行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkdir newdir/subdir</span></span></code></pre></div><p>你的新 <code>mkdir</code> 也会告诉你创建子目录时都做了什么。</p><h3 id="别名也是一种保护" tabindex="-1">别名也是一种保护 <a class="header-anchor" href="#别名也是一种保护" aria-label="Permalink to “别名也是一种保护”">​</a></h3><p>别名的另一个好处是它可以作为防止你意外地删除或覆写已有的文件的保护措施。你可能听说过这个 Linux 新用户的传言，当他们以 root 身份运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -rf /</span></span></code></pre></div><p>整个系统就爆了。而决定输入如下命令的用户：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>rm -rf /some/directory/ *</span></span></code></pre></div><p>就很好地干掉了他们的家目录的全部内容。这里不小心键入的目录和 <code>*</code> 之间的那个空格有时候很容易就会被忽视掉。</p><p>这两种情况我们都可以通过 <code>alias rm=&#39;rm -i&#39;</code> 别名来避免。<code>-i</code> 选项会使 <code>rm</code> 询问用户是否真的要做这个操作，在你对你的文件系统做出不可弥补的损失之前给你第二次机会。</p><p>对于 <code>cp</code> 也是一样，它能够覆盖一个文件而不会给你任何提示。创建一个类似 <code>alias cp=&#39;cp -i&#39;</code> 来保持安全吧。</p><h3 id="下一次" tabindex="-1">下一次 <a class="header-anchor" href="#下一次" aria-label="Permalink to “下一次”">​</a></h3><p>我们越来越深入到了脚本领域，下一次，我们将沿着这个方向，看看如何在命令行组合命令以给你真正的乐趣，并可靠地解决系统管理员每天面临的问题。</p><hr>`,51)),i("p",null,[s[4]||(s[4]=e("via: ",-1)),t(a,{href:"https://www.linux.com/blog/learn/2019/1/aliases-protect-and-serve"},{default:l(()=>[...s[3]||(s[3]=[e("https://www.linux.com/blog/learn/2019/1/aliases-protect-and-serve",-1)])]),_:1})]),i("p",null,[s[9]||(s[9]=e("作者：",-1)),t(a,{href:"https://www.linux.com/users/bro66"},{default:l(()=>[...s[5]||(s[5]=[e("Paul Brown",-1)])]),_:1}),s[10]||(s[10]=e(" 选题：",-1)),t(a,{href:"https://github.com/lujun9972"},{default:l(()=>[...s[6]||(s[6]=[e("lujun9972",-1)])]),_:1}),s[11]||(s[11]=e(" 译者：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[7]||(s[7]=[e("wxy",-1)])]),_:1}),s[12]||(s[12]=e(" 校对：",-1)),t(a,{href:"https://github.com/wxy"},{default:l(()=>[...s[8]||(s[8]=[e("wxy",-1)])]),_:1})]),i("p",null,[s[15]||(s[15]=e("本文由 ",-1)),t(a,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...s[13]||(s[13]=[e("LCTT",-1)])]),_:1}),s[16]||(s[16]=e(" 原创编译，",-1)),t(a,{href:"https://linux.cn/"},{default:l(()=>[...s[14]||(s[14]=[e("Linux中国",-1)])]),_:1}),s[17]||(s[17]=e(" 荣誉推出",-1))])])}const x=d(c,[["render",h]]);export{C as __pageData,x as default};
